var lamp_lights := 0
var building_names := [
	"RIVER & RYE", "PENNY POST", "MILLER BOOKS", "JUNIPER", "THE FOUNDRY",
	"MARA'S COURIER", "NORTH BANK", "LANTERN", "PETERS", "CORNER", "MARKET HALL",
