]

func _ready() -> void:
	rng.seed = 20261121
	reserved = WorldData.RESERVED_RECTS.duplicate()
	reserved.append(Rect2(34.0, -38.0, 18.0, 18.0))
	reserved.append(Rect2(-52.0, 30.0, 18.0, 20.0))
