	for i in range(3):
		_sphere_in(pivot, Vector3(rng.randf_range(-0.35, 0.35), 1.05, rng.randf_range(-0.35, 0.35)), rng.randf_range(0.3, 0.5), _mat(Color("#547b58"), 1.0))

