extends Control
class_name GameRadar

var world: Node
var player: Node3D
var mission_manager: MissionManager
var wanted_system: WantedSystem
var scale_px := 1.12
var flash := 0.0

func _ready() -> void:
	custom_minimum_size = Vector2(200, 200)
	mouse_filter = Control.MOUSE_FILTER_IGNORE

func setup(world_node: Node, player_node: Node3D, mission_node: MissionManager, wanted_node: WantedSystem) -> void:
	world = world_node
	player = player_node
	mission_manager = mission_node
	wanted_system = wanted_node

func _process(delta: float) -> void:
	flash += delta
	queue_redraw()

func _draw() -> void:
	var full := Rect2(Vector2.ZERO, size)
	draw_rect(full, Color(0.025, 0.05, 0.065, 0.94))
	var map_rect := Rect2(7, 7, size.x - 14, size.y - 14)
	if player == null:
		return
	var center := size * 0.5
	# Building blocks.
	var blocks := [
		Rect2(-66, -46, 55, 44), Rect2(11, -46, 55, 44),
		Rect2(-66, 18, 55, 40), Rect2(11, 18, 55, 40),
		Rect2(-140, 20, 62, 78), Rect2(78, 20, 62, 78),
		Rect2(-140, 112, 128, 28), Rect2(12, 112, 128, 28)
	]
	for block in blocks:
		_draw_world_rect(block, Color(0.18, 0.15, 0.13, 0.95), map_rect, center)
	# River and promenade.
	_draw_world_rect(Rect2(-150, -150, 300, 92), Color(0.1, 0.28, 0.36, 0.95), map_rect, center)
	_draw_world_rect(Rect2(-150, -58, 300, 12), Color(0.43, 0.39, 0.3, 0.95), map_rect, center)
	# Roads.
	var road := Color(0.22, 0.24, 0.25, 0.98)
	_draw_world_rect(Rect2(-7, -46, 14, 186), road, map_rect, center)
	_draw_world_rect(Rect2(-142, 2, 284, 12), road, map_rect, center)
	_draw_world_rect(Rect2(-105, -40, 10, 182), road, map_rect, center)
	_draw_world_rect(Rect2(95, -40, 10, 182), road, map_rect, center)
	_draw_world_rect(Rect2(-142, 99, 284, 10), road, map_rect, center)
	# Objective.
	if mission_manager and not mission_manager.current.is_empty():
		var op := mission_manager.objective_position()
		var p := _to_screen(op, center)
		p.x = clampf(p.x, map_rect.position.x + 7.0, map_rect.end.x - 7.0)
		p.y = clampf(p.y, map_rect.position.y + 7.0, map_rect.end.y - 7.0)
		var gold := Color("#e7b45b")
		var diamond := PackedVector2Array([p + Vector2(0, -7), p + Vector2(7, 0), p + Vector2(0, 7), p + Vector2(-7, 0)])
		draw_colored_polygon(diamond, gold)
		draw_arc(p, 10.0, 0.0, TAU, 20, Color(1.0, 0.85, 0.5, 0.5), 1.2)
	# Civilian vehicles.
	var vehicles: Array = world.get("vehicles") if world else []
	for car in vehicles:
		if not is_instance_valid(car):
			continue
		var p := _to_screen(car.global_position, center)
		if map_rect.has_point(p):
			draw_rect(Rect2(p - Vector2(2, 2), Vector2(4, 4)), Color(0.85, 0.87, 0.82, 0.85))
	# Police.
	if wanted_system:
		var pulse := 0.55 + sin(flash * 9.0) * 0.45
		for pos in wanted_system.get_police_positions():
			var p := _to_screen(pos, center)
			if map_rect.has_point(p):
				draw_circle(p, 4.5, Color(0.9, 0.2, 0.16, pulse))
				draw_circle(p + Vector2(3, 0), 3.0, Color(0.2, 0.45, 1.0, 1.0 - pulse * 0.5))
	# Player arrow.
	var yaw := player.rotation.y
	var arrow := PackedVector2Array([
		Vector2(0, -9).rotated(-yaw), Vector2(6, 7).rotated(-yaw),
		Vector2(0, 4).rotated(-yaw), Vector2(-6, 7).rotated(-yaw)
	])
	for i in range(arrow.size()):
		arrow[i] += center
	draw_colored_polygon(arrow, Color("#f4ead2"))
	draw_polyline(arrow, Color(0.05, 0.08, 0.09, 0.9), 1.4)
	# Border and compass.
	draw_rect(full.grow(-1.0), Color(0.87, 0.7, 0.38, 0.75), false, 2.0)
	draw_string(ThemeDB.fallback_font, Vector2(center.x - 5.0, 20.0), "N", HORIZONTAL_ALIGNMENT_LEFT, -1, 12, Color(0.95, 0.87, 0.7, 0.9))
	draw_string(ThemeDB.fallback_font, Vector2(12.0, size.y - 10.0), "OLD TOWNE", HORIZONTAL_ALIGNMENT_LEFT, -1, 10, Color(0.75, 0.72, 0.62, 0.85))

func _draw_world_rect(world_rect: Rect2, color: Color, map_rect: Rect2, center: Vector2) -> void:
	var origin := _to_screen(Vector2(world_rect.position.x, world_rect.position.y), center)
	var r := Rect2(origin, world_rect.size * scale_px)
	r = r.intersection(map_rect)
	if r.size.x > 0.0 and r.size.y > 0.0:
		draw_rect(r, color)

func _to_screen(world_pos: Vector3, center: Vector2) -> Vector2:
	return center + Vector2((world_pos.x - player.global_position.x) * scale_px, (world_pos.z - player.global_position.z) * scale_px)

func _to_screen2(world_pos: Vector2, center: Vector2) -> Vector2:
	return center + Vector2((world_pos.x - player.global_position.x) * scale_px, (world_pos.y - player.global_position.z) * scale_px)

extends Control
class_name TouchPad

var controller: TouchControls
var main: Node
var player: FPSPlayer
var driving := false

var joystick_touch := -1
var joystick_origin := Vector2.ZERO
var joystick_vector := Vector2.ZERO
var look_touch := -1
var sprint_touch := -1
var mouse_joystick := false
var mouse_look := false
var last_mouse := Vector2.ZERO
var button_touches: Dictionary = {}
var enabled := false

const JOY_RADIUS := 78.0
const JOY_KNOB := 34.0
const DEAD_ZONE := 8.0

func _ready() -> void:
	mouse_filter = Control.MOUSE_FILTER_IGNORE
	set_process_input(true)

func set_enabled(value: bool) -> void:
	enabled = value
	visible = value
	if not value:
		_reset_all()
	queue_redraw()

func _input(event: InputEvent) -> void:
	if not enabled or not visible or get_tree().paused:
		return
	if event is InputEventScreenTouch:
		if event.pressed:
			_handle_press(event.position, event.index)
		else:
			_handle_release(event.position, event.index)
		get_viewport().set_input_as_handled()
	elif event is InputEventScreenDrag:
		if event.index == joystick_touch:
			_update_joystick(event.position)
		elif event.index == look_touch:
			_apply_look(event.relative)
		get_viewport().set_input_as_handled()
	elif event is InputEventMouseButton and event.button_index == MOUSE_BUTTON_LEFT:
		if event.pressed:
			_handle_mouse_press(event.position)
		else:
			_handle_mouse_release()
	elif event is InputEventMouseMotion:
		if mouse_joystick:
			_update_joystick(event.position)
		elif mouse_look:
			_apply_look(event.relative)

func _handle_press(pos: Vector2, index: int) -> void:
	if _joystick_center().distance_to(pos) < JOY_RADIUS + 18.0:
		joystick_touch = index
		joystick_origin = _joystick_center()
		_update_joystick(pos)
		return
	var hit := _button_at(pos)
	if not hit.is_empty():
		button_touches[index] = hit.name
		_activate_button(hit.name)
		queue_redraw()
		return
	if pos.x > size.x * 0.38:
		look_touch = index

func _handle_release(_pos: Vector2, index: int) -> void:
	if index == joystick_touch:
		joystick_touch = -1
		joystick_vector = Vector2.ZERO
		_release_move()
	elif index == look_touch:
		look_touch = -1
	if button_touches.has(index):
		var name := str(button_touches[index])
		button_touches.erase(index)
		if name == "sprint":
			sprint_touch = -1
			Input.action_release("sprint")
		queue_redraw()

func _handle_mouse_press(pos: Vector2) -> void:
	if _joystick_center().distance_to(pos) < JOY_RADIUS + 18.0:
		mouse_joystick = true
		joystick_origin = _joystick_center()
		_update_joystick(pos)
		return
	var hit := _button_at(pos)
	if not hit.is_empty():
		_activate_button(hit.name)
		queue_redraw()
		return
	if pos.x > size.x * 0.38:
		mouse_look = true
		last_mouse = pos

func _handle_mouse_release() -> void:
	if mouse_joystick:
		mouse_joystick = false
		joystick_vector = Vector2.ZERO
		_release_move()
	mouse_look = false
	if sprint_touch == -2:
		sprint_touch = -1
		Input.action_release("sprint")

func _update_joystick(pos: Vector2) -> void:
	var offset := pos - joystick_origin
	if offset.length() > JOY_RADIUS:
		offset = offset.normalized() * JOY_RADIUS
	joystick_vector = offset / JOY_RADIUS
	var x := joystick_vector.x if absf(joystick_vector.x) > 0.12 else 0.0
	var y := joystick_vector.y if absf(joystick_vector.y) > 0.12 else 0.0
	_set_action("move_right", maxf(0.0, x))
	_set_action("move_left", maxf(0.0, -x))
	_set_action("move_back", maxf(0.0, y))
	_set_action("move_forward", maxf(0.0, -y))
	queue_redraw()

func _set_action(action: String, strength: float) -> void:
	if strength > 0.06:
		Input.action_press(action, clampf(strength, 0.0, 1.0))
	else:
		Input.action_release(action)

func _release_move() -> void:
	Input.action_release("move_forward")
	Input.action_release("move_back")
	Input.action_release("move_left")
	Input.action_release("move_right")

func _apply_look(relative: Vector2) -> void:
	if player:
		player.add_touch_look(relative)

func _activate_button(name: String) -> void:
	match name:
		"jump":
			_pulse_action("jump")
		"interact":
			if player and player.interactor:
				player.interactor.force_interact()
		"sprint":
			sprint_touch = -2
			Input.action_press("sprint")
		"horn":
			if main and main.is_player_driving():
				main.current_vehicle.honk()
		"exit":
			if main and main.is_player_driving():
				main.current_vehicle.exit_vehicle()

func _pulse_action(action: String) -> void:
	Input.action_press(action)
	await get_tree().create_timer(0.12, true).timeout
	Input.action_release(action)

func _reset_all() -> void:
	joystick_touch = -1
	look_touch = -1
	sprint_touch = -1
	mouse_joystick = false
	mouse_look = false
	button_touches.clear()
	joystick_vector = Vector2.ZERO
	_release_move()
	Input.action_release("sprint")

func _joystick_center() -> Vector2:
	return Vector2(138.0, size.y - 138.0)

func _button_list() -> Array:
	var list: Array = [
		{"name": "jump", "pos": Vector2(size.x - 88.0, size.y - 106.0), "r": 42.0, "label": "JUMP"},
		{"name": "interact", "pos": Vector2(size.x - 196.0, size.y - 106.0), "r": 38.0, "label": "USE"},
		{"name": "sprint", "pos": Vector2(size.x - 88.0, size.y - 212.0), "r": 38.0, "label": "RUN"},
		{"name": "horn", "pos": Vector2(size.x - 196.0, size.y - 212.0), "r": 34.0, "label": "HORN"}
	]
	if driving:
		list.append({"name": "exit", "pos": Vector2(size.x - 300.0, size.y - 106.0), "r": 34.0, "label": "EXIT"})
	return list

func _button_at(pos: Vector2) -> Dictionary:
	for button in _button_list():
		if (button.pos as Vector2).distance_to(pos) <= float(button.r) + 10.0:
			return button
	return {}

func _process(_delta: float) -> void:
	if visible:
		queue_redraw()

func _draw() -> void:
	if not enabled:
		return
	var base := Color(0.04, 0.08, 0.09, 0.36)
	var border := Color(0.92, 0.82, 0.63, 0.42)
	var active := Color(0.92, 0.72, 0.37, 0.45)
	var text_color := Color(0.97, 0.93, 0.82, 0.88)
	var font := ThemeDB.fallback_font

	var center := _joystick_center()
	draw_circle(center, JOY_RADIUS, base)
	draw_arc(center, JOY_RADIUS, 0.0, TAU, 48, border, 2.0, true)
	draw_circle(center, JOY_RADIUS - 16.0, Color(0.03, 0.06, 0.07, 0.18))
	var knob := center + joystick_vector * (JOY_RADIUS - JOY_KNOB - 8.0)
	draw_circle(knob, JOY_KNOB, Color(0.8, 0.78, 0.66, 0.24))
	draw_arc(knob, JOY_KNOB, 0.0, TAU, 32, Color(0.97, 0.9, 0.74, 0.6), 2.0, true)
	_draw_centered(font, "MOVE", center + Vector2(0, JOY_RADIUS + 20.0), 12, Color(0.9, 0.87, 0.78, 0.55))

	for button in _button_list():
		var p: Vector2 = button.pos
		var r: float = button.r
		var pressed := (button.name == "sprint" and sprint_touch == -2)
		draw_circle(p, r, active if pressed else base)
		draw_arc(p, r, 0.0, TAU, 32, border, 2.0, true)
		_draw_centered(font, str(button.label), p + Vector2(0, 5), 13, text_color)

	if look_touch < 0 and not mouse_look:
		_draw_centered(font, "DRAG TO LOOK", Vector2(size.x - 200.0, size.y - 306.0), 12, Color(0.9, 0.87, 0.78, 0.5))

func _draw_centered(font: Font, text: String, center: Vector2, font_size: int, color: Color) -> void:
	var width := font.get_string_size(text, HORIZONTAL_ALIGNMENT_LEFT, -1, font_size).x
	draw_string(font, center - Vector2(width * 0.5, -font_size * 0.32), text, HORIZONTAL_ALIGNMENT_LEFT, -1, font_size, color)

